# owner: platform
import unittest

from hourglass.rounding import round_labels, round_span
from hourglass.models import Span


class RoundSpanTests(unittest.TestCase):
    def test_snaps_to_nearest_step(self):
        result = round_span(Span(542, 1033), 15)
        self.assertEqual(result, Span(540, 1035))

    def test_halfway_rounds_up(self):
        result = round_span(Span(547, 600), 15)
        self.assertEqual(result, Span(555, 600))

    def test_end_of_day_stays(self):
        result = round_span(Span(1400, 1440), 30)
        self.assertEqual(result.end, 1440)

    def test_collapsed_span_is_rejected(self):
        with self.assertRaises(ValueError):
            round_span(Span(541, 543), 15)


class LabelTests(unittest.TestCase):
    def test_label_format(self):
        labels = round_labels([Span(540, 1035)], 15)
        self.assertEqual(
            labels, ["09:00-17:15 (8h 15m)"]
        )

    def test_one_label_per_span(self):
        spans = [Span(541, 601), Span(721, 781)]
        labels = round_labels(spans, 30)
        self.assertEqual(len(labels), 2)

    def test_empty_list(self):
        self.assertEqual(round_labels([], 15), [])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 120):
            with self.assertRaises(ValueError):
                round_labels([Span(540, 600)], step)

    def test_bad_step_raises_without_spans(self):
        with self.assertRaises(ValueError):
            round_labels([], 0)

    def test_good_steps_are_accepted(self):
        for step in (1, 5, 6, 10, 15, 20, 30, 60):
            round_labels([Span(540, 600)], step)
